n\nssl._create_default_https_context = ssl._create_unverified_context\n\n# Try the BLS website directly with proper headers\nurls = [\n    \"https://www.bls.gov/cpi/tables/supplemental-files/home/cpi-u-1960-1969.txt\",\n]\n\nfor url in urls:\n    try:\n        req = urllib.request.Request(url, headers={\n            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',\n            'Accept': 'text/html,application/xhtml+xml'\n        })\n        with urllib.request.urlopen(req, timeout=10) as response:\n            content = response.read().decode('utf-8')\n            print(content[:2000])\n            break\n    except Exception as e:\n        print(f\"Failed: {e}\")\n        \n# Let me also try from the historical CPI data website\nprint(\"\\n\\nTrying another source...\")\n\n# Try YNAB/nickdanthelender website which has historical CPI\nurl2 = \"https://www.nickdh.com/consumer-price-index-historical-data\"\ntry:\n    req = urllib.request.Request(url2, headers={'User-Agent': 'Mozilla/5.0'})\n    with urllib.request.urlopen(req, timeout=10) as response:\n        data = response.read().decode('utf-8')\n        if '1960' in data:\n            # Find the relevant section\n            start = data.find('1960')\n            print(data[start:start+500])\nexcept Exception as e:\n    print(f\"Error: {e}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
